if (typeof WN !== 'undefined'){ WN.ver = 'v338'; WN.items = [
  ['ท่าจับอาวุธเป็นธรรมชาติ · การโจมตีมีน้ำหนัก ง้าง ฟัน ตามแรง · การร่ายเวทพลิ้วไหวขึ้น', 'Natural grips · attacks with weight: wind-up, strike, follow-through · livelier spellcasting'],
  ['อาชีพไม่มีหมวกติดตัวแล้ว เห็นทรงผมเต็ม ๆ', 'Classes no longer come with a hat: your hair shows in full'],
  ['อาวุธทุกชิ้นโฉมใหม่ เห็นชัดในมือ อาวุธประจำสายมีลวดลายของตัวเอง', 'Every weapon has a new look and reads clearly in hand; class weapons carry their own designs'],
  ['ชุดเซตทุกชุดมีหน้าตาของตัวเองแล้ว', 'Every set now has a look of its own'],
  ['บอสบางตัวทิ้งชุดของมันไว้... ลองล่าดูสิ', 'Some bosses leave their own sets behind... go hunting'],
  ['ชุดบางแบบให้เลือกเส้นทางเองได้', 'Some sets let you choose their path'],

  ['ชุดเกราะมีให้เลือก 3 แบบ: หนัก เบา และเสื้อคลุม', 'Armour now comes in three kinds: heavy, light and robes'],
  ['ขวานทองวาณิชของพ่อค้า · หน้าไม้สำหรับนักธนู · ของขั้นใหม่ช่วงปลายเกม', 'The Golden Merchant Axe · crossbows for archers · new late-game tiers'],
  ['ทุกสายมีชุดประจำสายแล้ว ใส่ครบชุดจะรู้เอง', 'Every line has its own sets now. Wear a full one and see.'],
  ['ไม่มีเพื่อน? ชวนนักผจญภัย AI ลงดันเจียนด้วยกันได้', 'No friends around? Bring AI adventurers into a dungeon'],
  ['ลองทักนักผจญภัย AI ดูสิ', 'Try saying hello to an AI adventurer'],

  ['นักผจญภัย AI มาใช้ชีวิตอยู่ในโลกวายราแล้ว', 'AI adventurers now share the world of Vayra'],
  ['บอสในทุ่งรู้ตัวก่อนบุก ระวังสายตาของมันให้ดี', 'Field bosses now notice you before they charge. Watch out.'],
  ['ลูกศรทองช่วยนำทางนักผจญภัยหน้าใหม่', 'A gold arrow guides new adventurers'],
  ['ดันเจียน: ผู้พิทักษ์ที่รออยู่ข้างในไม่ควรสู้ลำพัง · Auto ยอมสู้ผู้พิทักษ์แล้ว', 'Dungeons: the guardian inside is no foe to face alone · Auto now fights it'],
  ['ทุ่งมือใหม่ปลอดภัยขึ้น · หน้าต่างวาร์ป ร้านเหรียญ ร้านยา และช่องสกิลว่าง เข้ากับ UI ใหม่', 'Safer beginner fields · warp window, coin shop, potion shop and empty skill slots in the new look'],
  ['ตรวจ UI ละเอียดทุกขนาดจอ: ป้ายชื่อ/เควสต์บนมือถืออ่านง่ายขึ้น · ปุ่มสกิลไม่โดนชิปทับ · หน้าจอตาย กล่องสอนเล่น หน้าต่างความสำเร็จ ร้านยา นายคลัง เข้ากับ UI ใหม่ อ่านชัด', 'A thorough UI pass: readable name/quest cards on phones · skill buttons clear of the chips · death screen, tutorial, achievements, shop and bank match the new look'],
  ['ไล่แก้ UI ทุกขนาดจอ: ปุ่มแชทอยู่ข้าง EXP ทั้ง PC และมือถือ · แบนเนอร์เทศกาล/ข่าวบอสไม่ทับเป้าหมายแล้ว · หน้าต่างคุยกับ NPC และวาร์ปเป็นธีมแก้วเดียวกัน · ลบลานลายตารางวงแหวนทองในสวรรค์', 'A UI sweep on every screen size: the chat button sits by EXP on PC and phone · festival and boss banners no longer cover the target · NPC talk and warp windows in the same glass theme · heaven\'s checkered gold-ring courts removed'],
  ['เวทมนต์ติดคริได้แล้ว (โอกาสเท่ากับตีปกติ แรงเท่ากัน)', 'Spells can now crit (the same chance and power as a weapon hit)'],
  ['เมนูใหม่: แผงแก้วสีเข้ม ไอคอนกลมเรืองแสงพร้อมชื่อ ใช้พื้นที่เต็มจอ ไม่มีแถบเลื่อนเกะกะ · ปุ่มร้านค้าทองใหญ่ กรอบเรืองแสง ไม่เด้งไปมา · ปุ่มแชทเป็นแก้วเข้ากับหน้าจอ', 'A new menu: a dark glass panel of glowing round icons with names, using the free height, no scrollbar · a big gold shop orb with a glowing frame that stays still · a glass chat button that matches'],
  ['พายุอสนีบาตหน้าตาเดิมแต่เนียนขึ้น: ลำพายุเป็นหมอกนุ่ม สายฟ้าโค้ง ไม่มีขอบเหลี่ยม · ลบเสาไฟทอง โคมทอง รูปปั้น และลานลายตารางกลางเมือง', 'Thunder Tempest keeps its look but is smooth: a soft misty funnel, curved lightning, no hard edges · golden lamp posts, lanterns, statues and the checkered plaza removed'],
  ['คอมโบตีปกติมีเสียงของแต่ละอาชีพ จังหวะที่ 3 เสียงเต็ม: ดาบกังวาน ระฆังหมอยา เหรียญกระทบของพ่อค้า แมวขู่ หมาหอน… · ท่าคอมโบลื่นขึ้น ไม่แวบท่าเก่า และเร็วขึ้นตามความเร็วตี', 'Combo hits sound like their class, the third the fullest: a ringing blade, healer bells, the merchant\'s coins, a cat hiss, a dog howl… · combo poses run smoother, no flash of the old pose, faster with attack speed'],
  ['มอนฟาดอาวุธตามชนิด: กระบองยกเหนือหัวแล้วทุบ หอกถอยง้างแล้วพุ่งแทง ขวานสับ ดาบสองมือฟันลงพื้น', 'Monsters strike the way their weapon does: clubs come down from overhead, spears draw back and thrust, axes chop, greatswords hew to the ground'],
  ['แก้หน้าจอตายกระพริบรัว ๆ บนมือถือ · โหมดเบาสำหรับมือถือช้าหรือเอฟเฟคต่ำ (ขอบไม่หมุน ไม่เบลอ) · แก้ปุ่มยาใหญ่เต็มจอเมื่อจัดตำแหน่งปุ่มเอง · ปุ่มร้านค้าบน PC เรียงแถวเดียวกับปุ่มอื่น · ปรับสมดุล 6 สาย', 'Fixed the death screen flickering on phones · a lite mode for slow phones or low effects (rims still, no blur) · fixed giant potion buttons with a hand-made button layout · the PC shop orb lines up with the others · six lines rebalanced'],
  ['ตีปกติเป็นคอมโบ 3 จังหวะ ท่าของแต่ละอาชีพไม่ซ้ำกัน: นักดาบ ฟันเฉียง-ฟันย้อน-แทง · นักมวย แย็บ-เตะ-ศอก · เจ้าเหมียว ข่วนซ้าย-ขวา-ตะปบ ฯลฯ เท้าติดพื้นทุกท่า', 'Normal attacks are a three-hit combo of each class\'s own: the swordsman cuts, cuts back and thrusts · the boxer jabs, kicks and elbows · the cat rakes left, right and with both paws, and so on — feet always on the ground'],
  ['ตีโดนแล้วมีเอฟเฟคของอาชีพตัวเอง จังหวะที่ 3 ใหญ่สุด: เสี้ยวคมเหล็ก กลีบบัวแสง เหรียญทองกระจาย รอยข่วนชมพู เขี้ยวงับ ดาวประกายฟ้า ยันต์ห้าแฉก…', 'Every hit lands with an effect of its class, the third the biggest: steel crescents, lotus light, a burst of gold coins, pink claw marks, snapping fangs, cyan star sparks, a turning curse sigil…'],
  ['ท่าสกิลใหม่ 8 ท่า (หมุนลูกพลัง คุกเข่าพนมมือ อวยพร ไขว้แขนกางออก เรียกจากพื้น หมุนไม้เท้า ก้าวหลบ รวมสมาธิ) · ไม่มีท่าไหนซ้ำเกิน 4 สกิลในอาชีพเดียว · สกิลที่ไม่มีท่ามีท่าแล้ว', '8 new skill poses (orb, kneeling prayer, blessing, crossed-arm release, a call from the ground, staff wheel, sidestep, focus) · no pose stands for more than 4 skills of one class · skills that had no pose now have one'],
  ['หน้าต่างทุกบานเข้ากับ UI ใหม่: กรอบแก้วขอบรุ้งเรืองแสง หัวหน้าต่างแก้วสีเข้ม ปุ่มปิดเป็นลูกแก้ว · ข้างในพื้นขาวอมลาเวนเดอร์ ปุ่มและแท็บสีม่วง-ฟ้า ตัวหนังสือสีคราม · รูปไอเทมและสีความหายากเหมือนเดิม', 'Every window matches the new look: glowing rainbow-rimmed glass frames, dark glass title bars, glass close buttons · inside, lavender-white panels, violet-cyan buttons and tabs, indigo lettering · item art and rarity colours unchanged'],
  ['ป้ายชื่อมุมซ้ายบนแบบใหม่: แผงแก้วขอบไล่สีแบบเดียวกับแผงอื่น รูปตัวละครใหญ่ในวงออร่า ชิป Lv และ Job อยู่ข้างชื่อ หลอด HP/SP มีป้ายบอก', 'A new top-left name plate: the same rainbow-rimmed glass as the other panels, a bigger portrait in its aura ring, Lv and Job chips beside the name, labelled HP/SP bars'],
  ['หน้าจอเล่นใหม่ทั้งหมด เหมือนกันทั้งมือถือ ไอแพด และ PC: แผงแก้วสีเข้มขอบรุ้ง ตัวหนังสือขาว · รูปตัวละครในวงออร่าหมุน หลอด HP/SP เรืองแสงมีประกายวิ่ง · เป้าหมายเป็นแคปซูลกลางจอ', 'A new play screen, the same on phone, iPad and PC: dark glass panels with rainbow rims and white lettering · the portrait in a turning aura ring, glowing HP/SP bars with a running sheen · the target in a pill at the top'],
  ['ขวาบน: ปุ่มกลม 4 สี ร้านค้า สกิล กระเป๋า เมนู แผนที่ย่ออยู่ใต้ · ซ้ายล่าง: EXP กับนาฬิกา · แชทโปร่งไม่บังจอ', 'Top right: four colour orbs — shop, skills, bag, menu — with the minimap under them · bottom left: EXP and the clock · a see-through chat'],
  ['ปุ่มโจมตีวงออร่าหมุนมีประกายวนรอบ · PC: ช่องสกิลเรียงเป็นพัดสองวงสมมาตรรอบปุ่มโจมตี ยาอยู่ด้านบน ปุ่มเล็กเรียงข้าง · จอยมือถือเป็นวงแก้วลูกจอยเรืองแสง', 'An aura attack button with orbiting sparks · PC: the skill slots fan round it in two symmetrical rings, potions above, small buttons beside · the touch joystick a glass ring with a glowing orb'],
  ['มอนไม่มีปีกแปะธรรมดาแล้ว ตัวที่ตำนานมีปีกใส่ปีกแฟชั่น (กินนร ปีกหงส์ · กินรีทอง ปีกกนกทอง · ภูต ปีกค้างคาว…) · มอน 31 ชนิดที่ชุดสีหม่นได้ชุดสีสดตามธาตุ ขอบทอง สร้อย กำไล', 'No more plain painted wings on monsters; the ones whose legend has wings wear a fashion wing (kinnorn swan wings, golden kinnaree kanok wings, imps bat wings…) · 31 monsters in drab clothes get bright outfits by element, with gold trim, necklaces and armbands'],
  ['อาวุธของมอนทุกตัวเรืองแสง แต่ละชนิดสีไม่ซ้ำกัน · หัวหน้าฝูงเรืองแรงกว่า · บอส: แสงหลายชั้น ประกายวิ่งขึ้นใบดาบ ละอองวนรอบ ดาวที่ปลายอาวุธ แรงขึ้นตอนง้างสกิล', 'Every monster weapon glows, each kind in a colour of its own · pack leaders brighter · bosses: layered light, a shine running up the blade, circling motes and a star at the tip, stronger as a move winds up'],
  ['มอนถืออาวุธตามความเหมาะสม: ยักษ์และทวารบาลถือกระบอง (ท้าวเวสสุวรรณกระบองทอง) ทหารและเทพรักษาถือหอกพู่แดง อสูรถือขวาน ปีศาจใช้กรงเล็บ บางตัวถือคาตานะหรือดาบใหญ่ · เนื้อโลหะตามธาตุ', 'Monsters carry fitting weapons: yakshas and temple guardians a club (Vessavana\'s is gold), soldiers and guards a red-tasselled spear, asuras an axe, fiends claws, some a katana or greatsword · the metal follows the element'],
  ['ปีกดูสมจริงทั้ง 8 ทิศ: กางเฉียงไปด้านหลังเป็นตัว V หมุนตามตัว ปีกข้างไกลหดสั้นและหลบหลังตัว มุมข้างเห็นทั้งสองปีก', 'Wings look real from all 8 directions: swept back in a V and turning with the body, the far wing foreshortened behind it, both wings seen from the side'],
  ['บอสที่มีปีกใส่ปีกแฟชั่นแบบสุ่มทุกครั้งที่เกิด (นางฟ้า ปีศาจ หงส์เพลิง ผลึก ครุฑกนก ห้วงจักรวาล…)', 'Winged bosses wear a random fashion wing each time they appear (angel, demon, phoenix, crystal, kanok garuda, cosmic void…)'],
  ['ท่าสกิลใหม่ 7 ท่าให้นักเวท ไสยเวท ผู้อัญเชิญ นินจา พราน: ผลักพลัง ชูไม้เท้าเรียกฟ้า กวาดแขน คุกเข่ายิง ประสานมือพ่นไฟ ประสานมือเหนือหัว สะบัดดาวเป็นพัด', '7 new skill poses for mage, hexer, summoner, ninja and hunter: force push, staff raised to the sky, sweeping arm, kneeling shot, fire seal, overhead seal, fan of stars'],
  ['ธรณีสูบ: รอยแยกลามและหลุมยุบ-ปิดนุ่มนวลขึ้น ไม่มีเศษค้าง · สวรรค์: เอาบ่อฟ้ามีเมฆและเสาเทวดาออก · Auto ใช้เวทใหญ่ของนักเวทบ่อยขึ้น (มอน 2 ตัวขึ้นไปหรือหัวหน้าฝูง/บอส)', 'Earth Swallow: the cracks spread and the pit sinks and closes smoothly, nothing left behind · heaven: sky ponds and deva pillars removed · Auto casts the mage\'s great spells more (two monsters together, or a pack leader or boss)'],
  ['สายที่ไม่ใช้ INT (นักดาบ พราน นักมวย นักย่อง พ่อค้า เจ้าเหมียว เจ้าตูบ) ฟื้น SP ถี่เท่าสายเวท บวกโบนัสตามเลเวล และสกิลกิน SP น้อยลง 45% · เดิมเลเวล 115 ฟื้นแค่ราว 0.75 SP/วินาที (สายเวท 10) SP หมดใน 6 วินาทีแล้วได้แต่ตีธรรมดา สกิลหลายตัวแทบไม่ได้ใช้', 'Classes without INT (Swordsman, Hunter, Muay, Rogue, Merchant, Cat, Dog) get SP back as often as casters plus a share by level, and their skills cost 45% less SP · at Lv 115 they used to get back about 0.75 SP a second (casters 10), ran dry in 6 s and could only swing — many skills went almost unused'],
  ['ปรับพลังทุกสายจากรายงานสมดุลเต็ม 4 รอบ: ทุกสายเก็บเลเวลเร็วใกล้กัน (เดิมห่างกันเกือบ 2 เท่า) · เวทใหญ่ของนักเวท (พายุ ธรณีสูบ น้ำท่วม) ร่ายเร็วขึ้นและคูลดาวน์สั้นลง', 'Every class tuned from four full balance reports: all level at a similar pace (the gap was almost 2×) · the mage\'s great spells (Tempest, Earth Swallow, Deluge) cast faster with shorter cooldowns'],
  ['แก้: บางวันตัวละครเลเวลต่ำได้ภารกิจรายวันให้ล่าในนครอาเรนซึ่งไม่มีมอน (เกิด error) · แก้ Auto: ไม่ใช้ «ขว้างหิน» เมื่อมีสกิลโจมตีของอาชีพแล้ว · ไม่ใช้ «ปฐมพยาบาล» เมื่อฟื้นได้ไม่ถึง 5% ของ HP · สกิลที่ใช้ไม่ได้ (เงินไม่พอ ฯลฯ) ไม่ถูกกดซ้ำจนสกิลอื่นไม่ได้ใช้ (พ่อค้าที่ไม่มีเงินเคยกด «ถล่มทอง» 158 ครั้งต่อนาทีโดยไม่ออกเลย)', 'Fixed: some days a low-level hero got a daily hunt in Aren, which has no monsters (an error) · Auto fixes: no Stone Throw once you have attack skills of your job · no First Aid once it heals under 5% of your HP · a skill that cannot go off (not enough Bia, etc.) is no longer tried again and again while the rest wait (a merchant without Bia tried Gold Rush 158 times a minute)'],
  ['พรานเลเวล 100 ขึ้นไปตีแรงขึ้น · พ่อค้าอาชีพขั้นสามตีแรงขึ้น · รายงานสมดุล: Lv 115 พราน 54% → 83% พ่อค้า 55% → 87% ของค่าเฉลี่ย · Lv 80 ทั้งคู่ราว 95% · อัปสเตตัสอัตโนมัติ: ช่วงต้นลง VIT มากขึ้น สายร่ายหยุดลง DEX เมื่อร่ายเร็วสุดแล้ว', 'Hunters from Lv 100 and merchants on their third job hit harder · balance report: at Lv 115 the hunter went from 54% to 83% and the merchant from 55% to 87% of the average · both about 95% at Lv 80 · auto stats: more VIT early on, and casters stop raising DEX once they cast as fast as they can'],
  ['Auto อัปสเตตัสให้ได้: เปิดสวิตช์ «อัปสเตตัสให้อัตโนมัติ» ในหน้าตั้งค่า Auto แล้วระหว่างเปิด Auto แต้มที่เหลือจะลงสเตตัสหลักของอาชีพ (ปิดไว้เป็นค่าเริ่มต้น ใครอยากอัปเองก็อัปได้เหมือนเดิม)', 'Auto can spend stat points: switch on «Spend stat points for me» in Auto settings and, while Auto runs, leftover points go to your class\'s main stats (off by default; spend them yourself as before)'],
  ['ปรางค์ร้างมีในทะเลทราย หุบผา (หินทรายผุ ทรายทับฐาน) ดินแดนน้ำแข็ง (หิมะคลุมทุกชั้น น้ำแข็งย้อย) ชายฝั่งและริมแม่น้ำ (คราบเกลือ สาหร่าย เปลือกหอย) ด้วย · ถ้ำไม่มี · ช้าง กระทิง หมูป่าใหญ่ ไม่หลุดกรอบภาพตอนพุ่งโจมตีแล้ว', 'The ruined prang now also stands in deserts and canyons (worn sandstone, sand over its base), frozen lands (snow on every ledge, icicles) and coasts and riverbanks (salt crust, weed, shells) · not in caves · elephants, gaur and big boars no longer cross their frame edge when they strike'],
  ['เอาซุ้มหินทราย ผลึกน้ำแข็ง/อเมทิสต์ และซากเรือออกจากแมพล่า · จุดเด่นที่เหลือ: ปรางค์ศิลาแลงร้าง (ซากเมือง ป่าช้า) และน้ำตกหน้าผา', 'The sandstone arch, the ice/amethyst crystals and the shipwreck taken off the hunting maps · the landmarks left: the ruined laterite prang (ruins, graveyards) and the cliff waterfalls'],
  ['แก้: ผู้เล่นใหม่เปิด Auto ในทุ่งสุวรรณินแล้วตายราวทุก 30 วินาที เพราะหมูป่า Lv 9 กับโคมผี Lv 13 (ตีก่อน) อยู่ปนทั่วแมพจนถึงประตูทางเข้า · ตอนนี้จัดตามความอันตรายแบบนครอาเรนเดิม: มอนอ่อนข้างประตูจากเมือง กลางแมพมอนกลาง หมูป่าฝั่งตะวันออก โคมผีออกเฉพาะกลางคืนฝั่งตะวันออก', 'Fixed: a new player on Auto in the Suwannin Fields died about every 30 s — Lv 9 boars and Lv 13 lanterns (which attack first) were spread over the whole map right up to the gate · now laid out by danger as in old Aren: the weak ones by the gate from town, the middle ones in the middle, boars to the east, lanterns only at night, far east'],
  ['Auto เลือกตีมอนที่เลเวลใกล้ตัว (ไม่เกิน +5) ก่อน ถือว่าหัวหน้าฝูงแรงกว่า 5 เลเวล · มอนที่เข้ามาตีก่อนยังสู้กลับตามเดิม · ทดสอบ: ผู้เล่นใหม่ 20 นาทีถึง Lv 16 ตาย 1 ครั้ง (เดิม 40 นาทีถึง Lv 11 ตาย 77 ครั้ง)', 'Auto picks monsters near its own level first (up to +5) and counts a pack leader 5 levels higher · a monster that attacks is still fought back · test: a new player reached Lv 16 in 20 min with 1 death (was Lv 11 in 40 min with 77)'],
  ['ทุกแมพล่ามีจุดเด่นตามดินแดน: น้ำตกหน้าผา (น้ำทองในสวรรค์ ลาวาในดินแดนภูเขาไฟ) เพิ่มอีก 10 แบบดินแดน · ปรางค์ศิลาแลงร้างมีเถาวัลย์และไทรขึ้น (ซากเมือง ป่าช้า) · ซุ้มหินทรายเดินลอดได้ (ทะเลทราย หุบผา) · กลุ่มผลึกน้ำแข็ง/อเมทิสต์ (ดินแดนน้ำแข็ง ถ้ำ) · ซากเรือสำเภาเกยตื้น (ชายฝั่ง ริมแม่น้ำ)', 'Every hunting map has a landmark of its land: a cliff waterfall (gold water in heaven, lava in the volcanic lands) on 10 more kinds of land · a ruined laterite prang with vines and a fig (ruins, graveyards) · a sandstone arch you can walk under (deserts, canyons) · ice or amethyst crystals (frozen lands, caves) · a wrecked junk on the sand (coasts, riverbanks)'],
  ['มอนธรรมดาโจมตีขยับร่างจริง: ง้างหัว ยกขาหน้า แล้วพุ่งงับอ้าปาก หางสะบัด งูยกตัวแล้วฉก (ไม่มีสกิลเพิ่ม) · ภาพมอนสี่ขาตัวยาวไม่ถูกตัดขอบตอนพุ่ง', 'Ordinary monsters attack with their bodies: head up and a front paw raised, then a lunge with the jaw wide, tail lashing; a snake rears and strikes (no new skills) · long four-legged monsters are no longer cut off at the frame edge when they lunge'],
  ['แมพล่ามอนทุกแมพ: ต้นไม้ไม่กระจายทั่วแมพเท่า ๆ กันแล้ว แต่ขึ้นเป็นดงมีลานโล่งคั่น ป่าหนาริมขอบแมพ และมีต้นเดี่ยวกลางลานบ้าง (ชนิดและจำนวนต้นไม้เท่าเดิม ไม่ขึ้นบนทางเดิน ในน้ำ หรือที่แคมป์)', 'Every hunting map: the trees no longer spread evenly over the whole map — they stand in groves with glades between, a denser wood along the edge and a lone tree here and there (the same kinds and number; never on the trail, in water or on the camp)'],
  ['หัวหน้าฝูง (★ สีทอง) ใช้สกิลมีท่าของร่างตัวเองแบบบอส: ปลุกฝูง = เงยหน้าคำราม · พุ่ง/คลื่น = ก้มหัวพุ่ง · ระดมยิง = ง้างหัวแล้วพ่น · ทุบพื้น = ยกตัวกระแทก · มอนธรรมดาเหมือนเดิม', 'Pack leaders (★ gold) act their skills with their own bodies, like bosses: the rally is a roar with the head thrown up, a charge or wave goes head-down, a volley is a breath, a slam rears and crashes · ordinary monsters as before'],
  ['ป่ารอบนครอาเรนและเมืองทางแยกบางลง (ต้นไม้น้อยลงราวครึ่ง) มือถือวาดเร็วขึ้น · วัดแล้วเวลาวาดต่อเฟรมเพิ่มจากก่อนมีป่าไม่เกิน 2–3 ms', 'The woods round Aren and the crossroad towns are thinner (about half the trees) so phones draw them faster · measured: no more than 2–3 ms a frame over the towns without woods'],
  ['เมืองทางแยกทั้ง 4 จัดผังใหม่ให้สมดุลทั้งซ้ายขวาบนล่าง: ป่ารอบขอบแมพ ทิวไม้สองข้างถนนสู่ประตู บ่อน้ำขอบธรรมชาติพร้อมดงไม้ทุกมุม ของประดับเป็นคู่ · ใช้พืชและน้ำของแต่ละดินแดน: ตลาดน้ำมีบ่อบัว เมืองทะเลทรายมีโอเอซิสกับต้นปาล์มและกระบองเพชร ป้อมน้ำแข็งมีสนหิมะกับบ่อน้ำแข็ง ดาวดึงส์มีไม้หิมพานต์กับบ่อบัวทอง', 'The four crossroad towns laid out in balance, mirrored both ways: woods round the edge, avenues to the gates, a natural pond with a grove in each quarter, ornaments in pairs · each in its own land: the floating market with lotus ponds, the desert town with oases, palms and cacti, the frost citadel with snowy pines and frozen ponds, Tavatimsa with Himmapan trees and golden lotus ponds'],
  ['บ่อน้ำทุกแมพขอบคดเป็นอ่าวเป็นแหลมมากขึ้น ไม่กลมเกือบเป็นวงกลมแล้ว · คลื่นริมน้ำเปลี่ยนจากวงรีเต็มวงเป็นระลอกสั้น ๆ · ต้นไม้ พุ่มไม้ หิน ที่เคยขึ้นกลางบ่อถูกเอาออก · นครอาเรน: เนินและหน้าผาเลื่อนลงมาให้เห็นตอนเล่น มีป่าบนเนิน ต้นไม้สองฝั่งเท่ากันพอดี', 'Ponds on every map have deeper bays and points, no longer nearly round · the lapping waves are short ripples instead of whole ovals · trees, bushes and rocks that stood in ponds are gone · Aren: the hills and cliffs moved down into view, with woods on top, and both sides now have exactly as many trees'],
  ['นครอาเรนจัดผังรอบเมืองใหม่ให้สมดุลซ้ายขวา: เนินและหน้าผาหินสองมุมทิศเหนือ (ประตูเหนือเปิดอยู่ตรงกลาง) · น้ำตก 1 แห่งตกจากหน้าผาฝั่งตะวันตกลงบ่อ ไหลต่อเป็นลำธาร ลุยน้ำได้ · ใต้หน้าผาฝั่งตะวันออกเป็นบ่อน้ำนิ่งขนาดเท่ากัน', 'Aren laid out in balance: a hill with a rock cliff in each north corner (the north gate open between) · one waterfall pours from the west cliff into its pool and runs on as a creek you can wade · under the east cliff a still pool of the same size'],
  ['บ่อน้ำทุกบ่อขอบคดแบบธรรมชาติ มีโคลนริมฝั่ง น้ำตื้นสีอ่อน กอกก ใบบัว ดอกบัว ก้อนหิน (บ่อกลมเดิมเอาออก) · ทุ่งนาสองบล็อกเท่ากันทิศตะวันตกเฉียงใต้และตะวันออกเฉียงใต้ · ป่ารอบขอบแมพ ทิวมะพร้าวสองข้างทางไปประตู แปลงดอกไม้เป็นคู่', 'Every pond has a natural, uneven bank: mud, pale shallows, reed clumps, lotus leaves and flowers, stones (the old round pond is gone) · two equal blocks of paddies south-west and south-east · woods round the map edge, palm avenues to the gates, flower beds in pairs'],
  ['เอาแผงตลาดและศาลาริมนาในนครอาเรนออกด้วย เหลือแต่ร้านค้ารอบลานเมือง ทุ่งนา และป่ารอบเมือง', 'Aren\'s market stalls and paddy pavilion removed too: only the shops round the plaza, the paddies and the woods remain'],
  ['แก้บั๊ก: หน้า «คุณตุยแล้ว» บางเครื่องขึ้นแต่หัวข้อ ไม่มีริบบิ้นและไม่มีปุ่มเกิดใหม่ ต้องรอ 3 นาที · เกิดกับเครื่องที่ปิดภาพเคลื่อนไหว (Windows ปิด «เอฟเฟกต์ภาพเคลื่อนไหว» หรือมือถือโหมดประหยัดแบต) ตอนนี้ปุ่มขึ้นครบทุกเครื่อง', 'Fixed: on some devices the «You died» sign showed only its title, with no ribbon and no buttons, so you had to wait 3 minutes · it happened on devices with animations turned off (Windows «animation effects» off, phone battery saver); the buttons now show on every device'],
  ['เอาบ้านเรือนไทยและห้องแถวในนครอาเรนออกทั้งหมด (พร้อมรั้ว ศาลพระภูมิ และลานบ้าน) · เหลือร้านค้ารอบลาน แผงตลาด และศาลาริมนา', 'All the Thai homes and shophouses in Aren removed (with their fences, spirit houses and yards) · the shops round the plaza, the market stalls and the paddy pavilion stay'],
  ['บอสใช้สกิลด้วยร่างของตัวเอง ไม่ใช่เอียงภาพทั้งตัวแบบเดิม: สัตว์สี่ขายกตัวพับขาหน้าแล้วกระแทกลง เงยหน้าอ้าปากเห็นเขี้ยวตอนคำราม ก้มหัวตั้งเขาตอนพุ่ง หันหัวพ่น หมุนตัวฟาดหาง ย่อตัวก่อนหายวับ · ช้างชูงวง · นกกางปีกตีลง · นาคยกตัวขึ้นแล้วฉกลง · ไดโนเสาร์และมังกรอ้าขากรรไกร · ทุกสกิลของบอสมีท่า ตีลงตอนวงแดงเต็มพอดี', 'Bosses act their moves with their own bodies instead of tilting the whole picture: four-legged bosses rear with the front legs folded and crash down, throw the head up with the jaws open to roar, lower the horns to charge, thrust the head to breathe, whip round with the tail lashing, crouch before vanishing · elephants raise the trunk · birds raise and beat their wings · nagas rear up and strike down · dinosaurs and dragons open their jaws · every boss move has a pose that lands as the red mark fills'],
  ['บอสไม่ลอยขึ้นจากพื้นตอนง้างสกิลแล้ว (เหลือแต่ตัวที่บินหรือวิญญาณ) · เข้าเฟสใหม่ (HP 70/40/15%) บอสเซถอยแล้วลุกขึ้นคำราม', 'Bosses no longer float off the ground while winding up (only fliers and spirits rise) · on a new phase (HP 70/40/15%) the boss reels back, then rises roaring'],
  ['วาบ: ตัวแตกสลายตรงที่ยืน มีภาพติดตาตามทาง แล้วค่อย ๆ ปรากฏตรงที่ไปถึง · พุ่ง/กลิ้งหลบ: ภาพติดตาเป็นแถว เส้นความเร็ว ฝุ่น · หายตัว: ควันพวย ตัวค่อย ๆ จางเป็นเงาระยิบ · ตีเร็ว: ภาพติดตาตามท่าฟันและเส้นลม (ยิ่งเร็วยิ่งเห็น) · บอสวาร์ปทิ้งเงาไว้ที่เดิม', 'Flash: the body breaks up where it stood, afterimages mark the path, it fades in where it lands · dash and dodge roll: a row of afterimages, speed streaks, dust · vanish: a puff of smoke, the body fades to a shimmer · fast attacks: afterimages of the swing and wind streaks (the faster, the more) · a boss that teleports leaves its afterimage behind'],
  ['เสือสมจริงขึ้น: ขายาว ตัวยาวต่ำแบบเสือจริง ลายที่ขาเป็นขีดด้านนอกไม่เป็นปล้องรอบขา อุ้งเท้าเล็กลง สะโพกและไหล่กลืนกับตัว แก้มขาว', 'A more lifelike tiger: long legs, a long low body, a few bars on the outer legs instead of rings, smaller paws, haunch and shoulder flowing into the body, white cheeks'],
  ['ท่าสกิลไม่กระโดดแล้วทุกท่า (เข่าลอย พยัคฆ์กระโจน กระโจนฟันลง หนุมานถวายแหวน จระเข้ฟาดหาง หมุนมีดคู่ กางปีกอัญเชิญหงส์) เท้าติดพื้นตลอดเหมือนท่าฟาดพื้น', 'No skill pose leaps any more (flying knee, tiger pounce, diving cut, uppercut, tail kick, twin spin, swan call): a foot stays on the ground, like the ground slam'],
  ['บ้านและตลาดในนครอาเรนวาดใหม่ให้เข้ากับร้านค้า: เรือนไทยบนฐานหิน หลังคาสองชั้นขอบทอง ช่อฟ้า โคมไฟ กระถางต้นไม้ 6 แบบ · ห้องแถวไม้สองชั้นริมถนน 6 ร้าน (ข้าวแกง ผ้าไหม ขนม น้ำชา จักสาน ดอกไม้) · แผงตลาด 6 แผง (ผลไม้ ปลาสด พวงมาลัย เครื่องปั้น ผ้าทอ ขนมไทย)', 'Aren\'s homes and market drawn anew to match the shops: Thai homes on stone plinths with two-tier gold-trimmed roofs, chofa, lanterns and pot plants (6 kinds) · six two-storey wooden shophouses by the roads (curry rice, silk, sweets, tea, basketry, flowers) · six market stalls (fruit, fresh fish, garlands, pottery, woven cloth, Thai sweets)'],
  ['นครอาเรนขยายเป็นหมู่บ้านกึ่งเมือง: ลานเมืองและร้านค้าวงกลมเป็นใจกลาง รอบนอกเป็นย่านบ้านเรือน (เรือนไทยยกใต้ถุน ศาลพระภูมิ ต้นกล้วย ไม้ผล ตุ่มน้ำ รั้วหน้าบ้าน) หมู่บ้านชาวนาริมทุ่งนา (กองฟาง ยุ้งฉาง) และถนนตลาดลงไปท่าเรือ · ถนนดินจากลานเมืองสู่ประตูทุกทิศ · ชาวบ้านเดินทั่วหมู่บ้าน', 'Aren grows into a village-town: the plaza and its ring of shops are the heart; around it lie the homes (raised Thai houses, spirit houses, banana and fruit trees, water jars, front fences), a farm hamlet by the paddies (haystacks, a granary) and a market lane down to the boat landing · earth roads from the plaza to every gate · townsfolk walk the whole village'],
  ['มอนสเตอร์ในแมพล่าลดลงเหลือราว 80 ตัวต่อแมพ (จาก 145) ลดความหนักเครื่อง · ท่าฟาดพื้นไม่กระโดดแล้ว · กดค้างช่องยาตอนเกมยุ่งไม่ดื่มเองแล้ว', 'Fewer monsters on hunting maps: about 80 a map (was 145), lighter on a phone · the ground slam no longer jumps · a long press on a potion slot no longer drinks it when the game is busy'],
  ['หน้าโหลดเข้าแมพ: เดินผ่านประตูหรือวาร์ปแล้วขึ้นหน้าโหลดทันที มีชื่อดินแดน ชื่อแมพ เลเวล แถบโหลด และเคล็ดลับ แทนภาพที่ค้างนิ่งระหว่างวาดแมพ', 'A loading screen: walk through a gate or warp and it shows at once, with the land, the map, its level, a moving bar and a tip, instead of a frozen picture while the map is painted'],
  ['ในเมืองไม่มีมอนสเตอร์และบอสแล้ว (ลดแลค): มอนเริ่มต้น 6 ชนิดและบอสของนครอาเรนย้ายไปแมพใหม่ «ทุ่งสุวรรณิน» (Lv 1–15) ออกประตูทิศตะวันออกของอาเรน อยู่ก่อนป่าไผ่กระซิบ · บทสอนพาเดินออกไป · เปิด Auto ในเมืองแล้วตัวละครเดินออกไปล่าเอง · เนื้อเรื่องบทแรกย้ายไปที่ทุ่ง', 'No monsters or bosses in town (less lag): Aren\'s six starter monsters and their boss moved to a new map, the Suwannin Fields (Lv 1–15), out of Aren\'s east gate and before the Whispering Bamboo · the tutorial walks you out · Auto switched on in town walks out to hunt · the first story chapter moved to the fields'],
  ['เมืองทางแยกทั้ง 4 เมืองกว้างขึ้น 25% · นครอาเรนทั้งแมพเป็นเขตเมืองแล้ว', 'The four crossroad towns are 25% wider · the whole of Aren\'s map is the town now'],
  ['แมพล่ามอนทุกแมพกว้างและสูงขึ้น 50% (พื้นที่ 2.25 เท่า) ต้นไม้และมอนเพิ่มตามพื้นที่ · นครอาเรนและเมืองทางแยกขนาดเท่าเดิม', 'Every hunting map is 50% wider and taller (2.25× the room), with trees and monsters to match · Aren and the crossroad towns keep their size'],
  ['ตัวละคร มอนสเตอร์ NPC สัตว์เลี้ยง และผู้เล่นคนอื่นใหญ่ขึ้น 20% เทียบกับต้นไม้และบ้าน · กล้องเริ่มต้นถอยออก 10% จึงเห็นรอบตัวกว้างขึ้นและตัวยังดูใหญ่ขึ้นบนจอ', 'Heroes, monsters, NPCs, pets and other players are 20% larger than trees and houses · the default camera sits 10% further out, so you see more around you and figures still read larger'],
  ['บอสมีท่าทางตามสกิลแล้ว (เดิมใช้ท่าโจมตีท่าเดียวทุกสกิล): ทุบพื้น/แผ่นดินไหว = ยกตัวขึ้น ค้าง แล้วทุบลงตอนวงเตือนเต็ม · พุ่งชน/คลื่น/ระดมยิง = ถอยย่อตัวแล้วพุ่ง · คำราม/คลั่ง = ย่อแล้วเงยตัวสั่น · อุกกาบาต/บ่อพิษ/ฟื้นพลัง/เรียกบริวาร = ลอยตัวเอนหลังร่าย · บอสร่างคนใช้ท่าของคน', 'Bosses now act out their skills (they used one attack pose for all): slam / quake = rear up, hang, crash down as the warning fills · charge / wave / barrage = draw back, then drive forward · roar / enraged = sink, then throw the front up and shake · meteor / pool / heal / summon = rise and lean back to channel · human bosses use human poses'],
  ['เหยี่ยวทั้ง 23 ชนิดเป็นนกล่าเหยื่อจริง: ตัวนก ปีกขน จะงอยปากงุ้ม หางแผ่ (เดิมถูกวาดด้วยร่างค้างคาวมีเขา)', 'All 23 hawks are real birds of prey: a bird body, feathered wings, a hooked beak, a broad tail (they were drawn on the bat body with horns)'],
  ['สกิลของบอสมีเอฟเฟกต์ตามดินแดนที่มันครอง: วังบาดาล = ฟองอากาศ · นรกอเวจี = เปลวไฟ · สวรรค์ = ดาวแสง · หุบเขาต้องห้าม = ขนนก · ความอ้างว้าง = ดวงวิญญาณ · แห้งแล้ง = หิน · อารยธรรม = กนกทอง · อุดมสมบูรณ์ = ใบไม้ · วงเตือนสีแดงยังชัดเท่าเดิม', "A boss's skills take the look of its land: bubbles under the sea, flames in Naraka, stars of light in Heaven, feathers, wisps, stones, gold kanok, leaves · the red warning shapes stay as clear as before"],
  ['เข้าแมพเร็วขึ้นอีก: ของประดับในแมพวาดตอนที่เข้ามาในจอครั้งแรก ไม่ได้วาดทั้งแมพตอนโหลด', 'Maps open faster again: a prop is painted when it first comes on screen, not all of them while loading'],
  ['งู: ลำตัวเรียวขึ้น เลื้อยเป็นตัว S หางเรียว มีเกล็ดบนหลังและแผ่นท้อง แลบลิ้นตอนยืนนิ่ง', 'Snakes: a slimmer body in a real S, a thin tail, scales on the back and belly plates, a flicking tongue'],
  ['ตั้งค่าใหม่: «เอฟเฟกต์ประจำอาชีพ» และ «เสียงหัวใจตอน HP ต่ำ» ปิดได้', 'New settings: «class skill effects» and «heartbeat at low HP» can be turned off'],
  ['เอฟเฟกต์สกิลใหม่ทุกอาชีพ: แต่ละสายมีสัญลักษณ์ของตัวเอง (ดาบ รูน ขนนก ดาวหมัด กลีบบัว จันทร์เสี้ยว กนก ดวงวิญญาณ เหรียญ อุ้งเท้า เขี้ยว ดาวกระจาย) · ตราวงเวทประจำสาย · บัพมีสัญลักษณ์หมุนรอบตัว · สกิลวงกว้างมีฝนสัญลักษณ์และเสาแสง', 'New skill effects for every class: each line has its own token (swords, runes, feathers, impact stars, lotus petals, crescent moons, kanok flames, spirit wisps, coins, paws, fangs, shuriken) · a class seal · buffs circle the hero · area skills rain tokens with light spears'],
  ['เอฟเฟกต์ออกตามท่าทาง: วงดาบตรงที่ฟัน ดาวตรงหมัด วงเตะระดับขา แสงรวมเหนือมือที่ชูขึ้น ตราลอยหน้ามือที่ทำมุทรา คลื่นเสียงตอนตะโกน โล่ตอนตั้งรับ · รอยโจมตีประจำสายเมื่อโดนเป้า', 'Effects follow the pose: a blade arc where the weapon swings, a star on the fist, an arc at leg height for a kick, light over raised hands, a sigil before a hand sign, sound waves from a shout, a shield on guard · each line leaves its own hit mark'],
  ['ตัวละครและมอนสเตอร์ทุกตัวแสงเงานุ่มขึ้น ขอบเรียบขึ้น · ตัวละครมีนิ้วมือ ส้นเท้าและพื้นรองเท้า · อูฐและแกะมีข้อขาและกีบ', 'Every character and monster has softer shading and a smoother edge · heroes have fingers, heels and soles · the camel and the sheep have leg joints and hooves'],
  ['เสียงใหม่: บอสคลั่ง · บอสเริ่มใช้สกิล · บอสปรากฏ · ตัวละครล้ม · HP ต่ำ (เสียงหัวใจ) · โดนสตัน · ขึ้น/ลงกวาง · ตีบวกสำเร็จ/ล้มเหลว · «ไม่พอ» · วาร์ปสั้น ใส่ของ วางของ', 'New sounds: boss rage · a boss starting a skill · a boss appearing · the hero falling · low HP (a heartbeat) · stunned · mounting / getting down · refine success / failure · «not enough» · blink, equip, drop'],
]; }

/* (v292) the version stays on screen, in the title bar beside the realm's name, so anyone can see which build is
   running (the owner and I spent a while not knowing whether the site had the newest pack) */
{ const putVer = () => { const h = document.querySelector('header.top'); if (!h || typeof WN === 'undefined' || !WN.ver) return;
    let b = h.querySelector('.gamever'); if (!b){ b = document.createElement('span'); b.className = 'gamever'; h.appendChild(b); } b.textContent = WN.ver; };
  putVer(); document.addEventListener('DOMContentLoaded', putVer);
  const st = document.createElement('style'); st.textContent = 'header.top .gamever{margin-left:10px;padding:1px 8px;border-radius:9px;font:700 12px/1.6 Sarabun,"Noto Sans Thai",sans-serif;color:#7a5418;background:rgba(255,236,170,.75);border:1px solid rgba(160,110,30,.35);vertical-align:middle}'; document.head.appendChild(st); }
